const queries = [
  { q: 'arabic dubbed film', origin: 'other',    lang: 'ar_dubbed' },
  { q: 'moroccan film darija', origin: 'moroccan', lang: 'ar' },
  { q: 'film arabe complet',  origin: 'moroccan', lang: 'ar' }
];
return queries.map(q => ({ json: q }));

const body = $input.first().json;
const query = $('Vimeo Queries').item.json;
const data = body?.data || [];

const MIN_DUR = 2100;

const candidates = data
  .filter(v => {
    const embeddable = v.embed?.badges?.embeddable || v.privacy?.embed === 'public';
    return embeddable && (v.duration || 0) >= MIN_DUR;
  })
  .map(v => {
    const vid = (v.uri || '').replace('/videos/', '');
    const year = v.release_time ? new Date(v.release_time).getFullYear() : null;
    const thumb = v.pictures?.sizes?.find(s => s.width >= 640)?.link ||
                  v.pictures?.sizes?.[0]?.link || null;
    return {
      platform: 'vimeo',
      platform_id: vid,
      title_raw: v.name || '',
      type: 'film',
      origin: query.origin || 'other',
      language: query.lang || 'ar_dubbed',
      category: 'drama',
      year,
      duration_sec: v.duration || null,
      poster_url: thumb,
      embed_url: `https://player.vimeo.com/video/${vid}`,
      embeddable: true,
      keyword: query.q,
      source_workflow: '06-vimeo-discover'
    };
  });

console.log(`[Vimeo] '${query.q}' → ${candidates.length} candidates`);
return [{ json: { candidates } }];
